import{_ as n,o,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-4-view-agency-profile/report3_spec.md","filePath":"feature/agency-workspace/3-4-4-view-agency-profile/report3_spec.md"}'),t={name:"feature/agency-workspace/3-4-4-view-agency-profile/report3_spec.md"};function s(a,e,l,c,g,d){return o(),r("div",null,[...e[0]||(e[0]=[i("<p><strong>3.4.4 View Agency Profile</strong></p><p><strong>Function Trigger</strong></p><p>A signed-in user opens the profile of an Agency they belong to, as Owner or as a Member. The profile is also shown right after selecting an Agency from the Agency list (3.4.1).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency Owner or Agency Member (any member role).</li><li><strong>Purpose</strong>: Show the branding and company information of an Agency to the people who work in it.</li><li><strong>Interface</strong>: Agency Profile page (/agencies/:agencyId/profile) — the branding section with name, logo, description, category, company size, contact details, brand colour, logo icon, tagline, founded year and social links. No separate profile data source; the page reads the same Agency profile used elsewhere.</li><li><strong>Data Processing</strong>: The system loads the Agency by its identifier, checks that the caller is the Owner or holds a Member record, and returns the branding and company information.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Agency Profile page:</p><ul><li>Header with name, logo, tagline and brand colour.</li><li>Company information: description, category, company size, website, phone, location, founded year (rendered as years in business).</li><li>Social links: Facebook, LinkedIn, Instagram.</li><li>No Workspace list and no Member list are shown here — company information only.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Agency identifier (agencyId) and a signed-in session.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: Agency profile — name, logoUrl, description, category, companySize, website, phone, location, brandColor, logoIcon, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, plus id, ownerId, status, createdAt, updatedAt. The caller&#39;s Agency Member records are used for the access check.</li><li><strong>Output</strong>: the profile of the Agency, restricted to branding and company information; no Workspace or Member data.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29 (analogous)</strong>: only the Owner, or a user holding a Member record, may view the profile. Any other signed-in user is refused with 400 NOT_AGENCY_MEMBER.</li><li>The Owner always has access, even with no Agency Member record; the Owner check stands on its own.</li><li>Every member role may view the profile — role does not narrow access.</li><li>The profile is not public; a user must be signed in and belong to the Agency.</li><li>This screen differs from the Agency Dashboard (3.4.2): profile carries branding and company information, dashboard carries management figures.</li><li>The profile response holds no internal detail beyond branding and company information.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>No signed-in session, or an invalid one → 401 UNAUTHORIZED, refused before Agency logic runs.</li><li>Agency does not exist → Display: <strong>MSG38</strong></li><li>Caller is neither the Owner nor a Member → Display: <strong>MSG39</strong></li><li>Agency already soft-deleted → the record is still returned, so Owner and Members can still view it. See 3.4.6 for removal behaviour.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens the profile of an Agency.</li><li>The client requests the Agency profile with the signed-in session.</li><li>The system confirms the session, then loads the Agency by its identifier.</li><li>The system confirms the caller is the Owner or holds a Member record.</li><li>The system returns the branding and company information.</li><li>The client renders the profile, including years in business.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: No signed-in session, or an invalid one → 401 UNAUTHORIZED, toast <strong>MSG22</strong>. 2.a2: The user signs in again and retries.</li><li>3.a1: Agency does not exist → 404 AGENCY_NOT_FOUND, toast <strong>MSG38</strong>. 3.a2: The user returns to the Agency list.</li><li>4.a1: Caller belongs to no part of the Agency → 400 NOT_AGENCY_MEMBER, toast <strong>MSG39</strong>; no profile data returned. 4.a2: The user returns to the Agency list and opens an Agency they belong to.</li><li>4.b1: Agency already soft-deleted → the profile is still returned; no error, no toast. 4.b2: The user continues viewing normally.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No Agency data is created, changed or removed.</li><li>The profile shows correct company information and exposes no internal information.</li></ul>",14)])])}const y=n(t,[["render",s]]);export{h as __pageData,y as default};
